export function getAsyncSearchIdQueryKey(
  args: InferRequestType<(typeof client._async_search)[':id']['$get']>,
) {
  return ['_async_search', '/_async_search/:id', args] as const
}

export function getAsyncSearchIdQueryOptions<
  TData = Awaited<
    ReturnType<
      typeof parseResponse<Awaited<ReturnType<(typeof client._async_search)[':id']['$get']>>>
    >
  >,
  TError = DefaultError,
>(
  args: InferRequestType<(typeof client._async_search)[':id']['$get']>,
  options?: ClientRequestOptions,
) {
  return queryOptions<
    Awaited<
      ReturnType<
        typeof parseResponse<Awaited<ReturnType<(typeof client._async_search)[':id']['$get']>>>
      >
    >,
    TError,
    TData,
    ReturnType<typeof getAsyncSearchIdQueryKey>
  >({
    queryKey: getAsyncSearchIdQueryKey(args),
    queryFn({ signal }) {
      return parseResponse(
        client._async_search[':id'].$get(args, { ...options, init: { ...options?.init, signal } }),
      )
    },
  })
}

export function injectAsyncSearchId<
  TData = Awaited<
    ReturnType<
      typeof parseResponse<Awaited<ReturnType<(typeof client._async_search)[':id']['$get']>>>
    >
  >,
  TError = DefaultError,
>(
  args: () => InferRequestType<(typeof client._async_search)[':id']['$get']>,
  options?: () => {
    query?: Omit<
      CreateQueryOptions<
        Awaited<
          ReturnType<
            typeof parseResponse<Awaited<ReturnType<(typeof client._async_search)[':id']['$get']>>>
          >
        >,
        TError,
        TData,
        ReturnType<typeof getAsyncSearchIdQueryKey>
      >,
      'queryKey' | 'queryFn'
    >
    options?: ClientRequestOptions
  },
) {
  return injectQuery(() => {
    const { query, options: clientOptions } = options?.() ?? {}
    return { ...getAsyncSearchIdQueryOptions<TData, TError>(args(), clientOptions), ...query }
  })
}

